INSERT INTO skills (code, subject_code, name) VALUES
    ('PLACE_VALUE_G1', 'MATH', 'Tens and Ones'),
    ('SHAPES_G1', 'MATH', 'Shapes and Their Sides'),
    ('TIME_HOUR_G1', 'MATH', 'Telling Time to the Hour'),
    ('MEASURE_G1', 'MATH', 'Measuring Length'),
    ('SIGHT_WORDS_G1', 'ENGLISH', 'Sight Words'),
    ('SHORT_VOWELS_G1', 'ENGLISH', 'Short Vowel Sounds'),
    ('DIGRAPHS_G1', 'ENGLISH', 'Sh, Ch, and Th Sounds'),
    ('COMPREHENSION_G1', 'ENGLISH', 'Reading Comprehension'),
    ('PUNCTUATION_G1', 'ENGLISH', 'Capitals and Punctuation'),
    ('NOUNS_VERBS_G1', 'ENGLISH', 'Nouns and Verbs'),
    ('PLURALS_G1', 'ENGLISH', 'One and More Than One'),
    ('OPPOSITES_G1', 'ENGLISH', 'Opposites');
INSERT INTO lessons (id, code, subject_code, grade_level, display_order, title, description) VALUES
    ('10000000-0000-0000-0000-000000000006', 'G1-PLACE-01', 'MATH', 'GRADE_1', 6, 'Tens and Ones', 'See how numbers up to 99 are built from tens and ones.'),
    ('10000000-0000-0000-0000-000000000007', 'G1-SHAPE-01', 'MATH', 'GRADE_1', 7, 'Shapes and Their Sides', 'Name flat shapes and count their sides and corners.'),
    ('10000000-0000-0000-0000-000000000008', 'G1-TIME-01', 'MATH', 'GRADE_1', 8, 'Telling Time to the Hour', 'Read a clock when the long hand points to 12.'),
    ('10000000-0000-0000-0000-000000000009', 'G1-MEASURE-01', 'MATH', 'GRADE_1', 9, 'Measuring Length', 'Compare lengths and measure with small units like paper clips.'),
    ('10000000-0000-0000-0000-000000000010', 'G1-ENG-SIGHT-01', 'ENGLISH', 'GRADE_1', 1, 'Sight Words', 'Read common words quickly without sounding them out.'),
    ('10000000-0000-0000-0000-000000000011', 'G1-ENG-VOWEL-01', 'ENGLISH', 'GRADE_1', 2, 'Short Vowel Sounds', 'Hear and read the short a, e, i, o, and u sounds.'),
    ('10000000-0000-0000-0000-000000000012', 'G1-ENG-DIGRAPH-01', 'ENGLISH', 'GRADE_1', 3, 'Sh, Ch, and Th Sounds', 'Two letters that work together to make one sound.'),
    ('10000000-0000-0000-0000-000000000013', 'G1-ENG-COMP-01', 'ENGLISH', 'GRADE_1', 4, 'Reading Comprehension', 'Read short stories and answer who, what, and where.'),
    ('10000000-0000-0000-0000-000000000014', 'G1-ENG-PUNCT-01', 'ENGLISH', 'GRADE_1', 5, 'Capital Letters and End Marks', 'Start sentences with a capital and end them with . ? or !'),
    ('10000000-0000-0000-0000-000000000015', 'G1-ENG-NOUNVERB-01', 'ENGLISH', 'GRADE_1', 6, 'Naming Words and Action Words', 'Tell nouns (naming words) from verbs (action words).'),
    ('10000000-0000-0000-0000-000000000016', 'G1-ENG-PLURAL-01', 'ENGLISH', 'GRADE_1', 7, 'One and More Than One', 'Add -s or -es to show more than one.'),
    ('10000000-0000-0000-0000-000000000017', 'G1-ENG-OPPOSITE-01', 'ENGLISH', 'GRADE_1', 8, 'Opposites', 'Find words that mean the opposite of each other.');
INSERT INTO exercises (id, lesson_code, skill_code, display_order, prompt, answer_index, explanation, hint) VALUES
    ('30000000-0000-0000-0000-000000000001', 'G1-COUNT-01', 'COUNTING', 4, 'Count the fish: fish fish fish fish fish fish. How many fish?', 0, 'There are 6 fish: 1, 2, 3, 4, 5, 6.', 'Touch each fish as you count it.'),
    ('30000000-0000-0000-0000-000000000002', 'G1-COUNT-01', 'COUNTING', 5, 'What number comes right before 15?', 0, 'Counting up goes 13, 14, 15, so 14 comes right before 15.', 'Count up and stop just before 15.'),
    ('30000000-0000-0000-0000-000000000003', 'G1-COUNT-01', 'COUNTING', 6, 'Which number is nineteen?', 0, 'Nineteen is 1 ten and 9 ones: 19.', 'Nineteen is a teen number, so it starts with 1.'),
    ('30000000-0000-0000-0000-000000000004', 'G1-ADD-01', 'ADDITION', 4, 'What is 5 + 2?', 2, '5 + 2 = 7.', 'Start at 5 and count up 2: 6, 7.'),
    ('30000000-0000-0000-0000-000000000005', 'G1-ADD-01', 'ADDITION', 5, 'What is 6 + 4?', 2, '6 + 4 = 10. 6 and 4 are a pair that makes 10!', 'Count up 4 from 6.'),
    ('30000000-0000-0000-0000-000000000006', 'G1-ADD-01', 'ADDITION', 6, 'What is 0 + 8?', 0, 'Adding 0 changes nothing, so 0 + 8 = 8.', 'What happens when you add nothing?'),
    ('30000000-0000-0000-0000-000000000007', 'G1-SUB-01', 'SUBTRACTION', 4, 'What is 8 - 5?', 2, '8 - 5 = 3.', 'Count back 5 from 8: 7, 6, 5, 4, 3.'),
    ('30000000-0000-0000-0000-000000000008', 'G1-SUB-01', 'SUBTRACTION', 5, 'What is 10 - 1?', 2, 'Taking away 1 gives the number just before: 10 - 1 = 9.', 'Which number comes right before 10?'),
    ('30000000-0000-0000-0000-000000000009', 'G1-SUB-01', 'SUBTRACTION', 6, 'What is 7 - 7?', 2, 'Taking away everything leaves nothing: 7 - 7 = 0.', 'If you have 7 and give away all 7, what is left?'),
    ('30000000-0000-0000-0000-000000000010', 'G1-CMP-01', 'COMPARISON', 4, 'Which number is greater: 14 or 41?', 2, '41 has 4 tens and 14 has only 1 ten, so 41 is greater.', 'Look at the tens digit first.'),
    ('30000000-0000-0000-0000-000000000011', 'G1-CMP-01', 'COMPARISON', 5, 'Which sign makes this true: 9 ? 4', 1, '9 is more than 4, so 9 > 4.', 'The open side of the sign faces the bigger number.'),
    ('30000000-0000-0000-0000-000000000012', 'G1-CMP-01', 'COMPARISON', 6, 'Which number is between 6 and 8?', 0, 'Counting 6, 7, 8 shows that 7 is between them.', 'Count from 6 to 8 out loud.'),
    ('30000000-0000-0000-0000-000000000013', 'G1-WORD-01', 'WORD_PROBLEMS', 4, 'Ana has 6 balloons. 1 pops. How many balloons does she have now?', 2, '6 balloons take away 1 popped balloon leaves 5.', 'Popping takes a balloon away, so subtract.'),
    ('30000000-0000-0000-0000-000000000014', 'G1-WORD-01', 'WORD_PROBLEMS', 5, 'There are 5 red cars and 4 blue cars. How many cars are there in all?', 2, '5 + 4 = 9 cars.', '"In all" means put the groups together.'),
    ('30000000-0000-0000-0000-000000000015', 'G1-WORD-01', 'WORD_PROBLEMS', 6, 'Ben has 10 grapes. He eats 3. How many grapes are left?', 2, '10 - 3 = 7 grapes are left.', 'Eating takes grapes away. Count back 3 from 10.'),
    ('30000000-0000-0000-0000-000000000016', 'G1-PLACE-01', 'PLACE_VALUE_G1', 1, 'How many tens are in the number 35?', 0, 'In 35, the 3 is in the tens place, so there are 3 tens.', 'The first digit tells you the tens.'),
    ('30000000-0000-0000-0000-000000000017', 'G1-PLACE-01', 'PLACE_VALUE_G1', 2, 'How many ones are in the number 52?', 2, 'In 52, the 2 is in the ones place, so there are 2 ones.', 'The last digit tells you the ones.'),
    ('30000000-0000-0000-0000-000000000018', 'G1-PLACE-01', 'PLACE_VALUE_G1', 3, 'What number has 2 tens and 6 ones?', 2, '2 tens is 20, and 6 more ones makes 26.', 'Write the tens digit first, then the ones digit.'),
    ('30000000-0000-0000-0000-000000000019', 'G1-PLACE-01', 'PLACE_VALUE_G1', 4, 'What number is 1 ten and 0 ones?', 0, '1 ten and no ones is 10.', 'A ten is a bundle of 10 ones.'),
    ('30000000-0000-0000-0000-000000000020', 'G1-PLACE-01', 'PLACE_VALUE_G1', 5, 'What is 40 + 7?', 1, '4 tens and 7 ones make 47.', '40 is 4 tens. Put the 7 ones after it.'),
    ('30000000-0000-0000-0000-000000000021', 'G1-PLACE-01', 'PLACE_VALUE_G1', 6, 'Which number has more tens: 28 or 31?', 1, '31 has 3 tens and 28 has 2 tens, so 31 has more tens.', 'Compare only the first digits.'),
    ('30000000-0000-0000-0000-000000000022', 'G1-SHAPE-01', 'SHAPES_G1', 1, 'Which shape has 3 sides and 3 corners?', 0, 'A triangle has 3 straight sides and 3 corners.', '"Tri" means three.'),
    ('30000000-0000-0000-0000-000000000023', 'G1-SHAPE-01', 'SHAPES_G1', 2, 'Which shape has 6 sides?', 2, 'A hexagon has 6 sides, like a honeycomb cell.', 'Think of the shape of a honeycomb.'),
    ('30000000-0000-0000-0000-000000000024', 'G1-SHAPE-01', 'SHAPES_G1', 3, 'How many corners does a square have?', 0, 'A square has 4 corners and 4 equal sides.', 'Point to each corner of a square and count.'),
    ('30000000-0000-0000-0000-000000000025', 'G1-SHAPE-01', 'SHAPES_G1', 4, 'Which shape has no straight sides?', 0, 'A circle is round all the way, with no straight sides.', 'Which shape can roll?'),
    ('30000000-0000-0000-0000-000000000026', 'G1-SHAPE-01', 'SHAPES_G1', 5, 'Which shape has 4 sides, with 2 long sides and 2 short sides?', 2, 'A rectangle has 4 sides: 2 long and 2 short.', 'A door is this shape.'),
    ('30000000-0000-0000-0000-000000000027', 'G1-SHAPE-01', 'SHAPES_G1', 6, 'How many sides does a pentagon have?', 1, 'A pentagon has 5 sides and 5 corners.', '"Penta" means five.'),
    ('30000000-0000-0000-0000-000000000028', 'G1-TIME-01', 'TIME_HOUR_G1', 1, 'The short hand points to 2 and the long hand points to 12. What time is it?', 1, 'When the long hand is on 12, it is exactly on the hour. The short hand says 2, so it is 2:00.', 'The short hand tells the hour.'),
    ('30000000-0000-0000-0000-000000000029', 'G1-TIME-01', 'TIME_HOUR_G1', 2, 'The short hand points to 9 and the long hand points to 12. What time is it?', 2, 'The short hand is on 9 and the long hand is on 12, so it is 9:00.', 'Look at where the short hand points.'),
    ('30000000-0000-0000-0000-000000000030', 'G1-TIME-01', 'TIME_HOUR_G1', 3, 'Which clock shows 5 o''clock?', 1, 'At 5 o''clock the short hand points to 5 and the long hand points to 12.', 'Find the clock with the short hand on 5.'),
    ('30000000-0000-0000-0000-000000000031', 'G1-TIME-01', 'TIME_HOUR_G1', 4, 'Which clock shows 11 o''clock?', 2, 'At 11 o''clock the short hand points to 11 and the long hand points to 12.', 'Look for the short hand on 11.'),
    ('30000000-0000-0000-0000-000000000032', 'G1-TIME-01', 'TIME_HOUR_G1', 5, 'It is 3 o''clock. What time will it be in 1 hour?', 1, 'One hour after 3:00 is 4:00. The short hand moves to the next number.', 'Count up one hour from 3.'),
    ('30000000-0000-0000-0000-000000000033', 'G1-TIME-01', 'TIME_HOUR_G1', 6, 'Where does the long hand point at any o''clock time?', 0, 'At every o''clock time the long hand points straight up to 12.', 'Think about how 7:00 or 8:00 looks.'),
    ('30000000-0000-0000-0000-000000000034', 'G1-MEASURE-01', 'MEASURE_G1', 1, 'A crayon and a broom. Which one is longer?', 0, 'A broom is much longer than a crayon.', 'Think about which one you could sweep the floor with.'),
    ('30000000-0000-0000-0000-000000000035', 'G1-MEASURE-01', 'MEASURE_G1', 2, 'A ribbon is 6 paper clips long. Another ribbon is 4 paper clips long. Which is longer?', 0, '6 is more than 4, so the 6-paper-clip ribbon is longer.', 'More paper clips means longer.'),
    ('30000000-0000-0000-0000-000000000036', 'G1-MEASURE-01', 'MEASURE_G1', 3, 'A pencil is 5 cubes long. A marker is 7 cubes long. How many cubes longer is the marker?', 2, '7 - 5 = 2, so the marker is 2 cubes longer.', 'Subtract the shorter length from the longer one.'),
    ('30000000-0000-0000-0000-000000000037', 'G1-MEASURE-01', 'MEASURE_G1', 4, 'When you measure with paper clips, how should you place them?', 0, 'Paper clips must touch end to end, with no gaps or overlaps, to measure correctly.', 'Gaps would leave parts of the object uncounted.'),
    ('30000000-0000-0000-0000-000000000038', 'G1-MEASURE-01', 'MEASURE_G1', 5, 'A tree and a flower. Which one is usually taller?', 2, 'Trees are usually much taller than flowers.', 'Which one can you climb?'),
    ('30000000-0000-0000-0000-000000000039', 'G1-MEASURE-01', 'MEASURE_G1', 6, 'Three sticks are 3, 8, and 5 blocks long. Which stick is the shortest?', 2, '3 is the smallest number, so the 3-block stick is the shortest.', 'Find the smallest number.'),
    ('30000000-0000-0000-0000-000000000040', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 1, 'Which word is "was"?', 0, '"was" is spelled w-a-s.', 'It starts with w.'),
    ('30000000-0000-0000-0000-000000000041', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 2, 'Which word is "they"?', 1, '"they" is spelled t-h-e-y.', 'Look at the last letter: y.'),
    ('30000000-0000-0000-0000-000000000042', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 3, 'Which word finishes the sentence: "I ___ to the park."', 0, '"I went to the park" makes sense.', 'Read the sentence with each word. Which sounds right?'),
    ('30000000-0000-0000-0000-000000000043', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 4, 'Which word is "said"?', 0, '"said" is spelled s-a-i-d.', 'This word has an i in it.'),
    ('30000000-0000-0000-0000-000000000044', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 5, 'Which word finishes the sentence: "Can you ___ me?"', 2, '"Can you help me?" makes sense.', 'Which word asks for a hand?'),
    ('30000000-0000-0000-0000-000000000045', 'G1-ENG-SIGHT-01', 'SIGHT_WORDS_G1', 6, 'Which word is "come"?', 1, '"come" is spelled c-o-m-e.', 'It has an o and an m.'),
    ('30000000-0000-0000-0000-000000000046', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 1, 'Which word has the short "a" sound, like in "apple"?', 1, '"map" has the short a sound: m-a-p.', 'Say each word slowly and listen to the middle.'),
    ('30000000-0000-0000-0000-000000000047', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 2, 'Which word has the short "e" sound, like in "egg"?', 1, '"bed" has the short e sound: b-e-d.', 'Listen for the sound at the start of "egg".'),
    ('30000000-0000-0000-0000-000000000048', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 3, 'Which word has the short "i" sound, like in "igloo"?', 1, '"pig" has the short i sound: p-i-g.', 'Say the words and listen to the middle sound.'),
    ('30000000-0000-0000-0000-000000000049', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 4, 'Which word has the short "o" sound, like in "octopus"?', 0, '"hot" has the short o sound: h-o-t.', 'Listen for the sound at the start of "octopus".'),
    ('30000000-0000-0000-0000-000000000050', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 5, 'Which word has the short "u" sound, like in "umbrella"?', 0, '"bug" has the short u sound: b-u-g.', 'Listen for the sound at the start of "umbrella".'),
    ('30000000-0000-0000-0000-000000000051', 'G1-ENG-VOWEL-01', 'SHORT_VOWELS_G1', 6, 'Change the vowel in "cat" to "u". What new word do you get?', 2, 'c-a-t becomes c-u-t: "cut".', 'Keep the c and the t. Only the middle letter changes.'),
    ('30000000-0000-0000-0000-000000000052', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 1, 'Which word starts with the "sh" sound?', 2, '"ship" starts with sh. The s and h work together to make one sound.', 'Shh! Be quiet! That''s the sound.'),
    ('30000000-0000-0000-0000-000000000053', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 2, 'Which word starts with the "ch" sound?', 0, '"chair" starts with ch, like a choo-choo train.', 'Think of the sound a train makes: choo-choo.'),
    ('30000000-0000-0000-0000-000000000054', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 3, 'Which word starts with the "th" sound?', 2, '"thumb" starts with th. Put your tongue between your teeth to say it.', 'Your tongue peeks out for this sound.'),
    ('30000000-0000-0000-0000-000000000055', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 4, 'Which word ends with the "sh" sound?', 0, '"fish" ends with sh: f-i-sh.', 'Say each word and listen to the very end.'),
    ('30000000-0000-0000-0000-000000000056', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 5, 'Which word ends with the "ch" sound?', 0, '"lunch" ends with ch: l-u-n-ch.', 'Listen for the choo-choo sound at the end.'),
    ('30000000-0000-0000-0000-000000000057', 'G1-ENG-DIGRAPH-01', 'DIGRAPHS_G1', 6, 'Which two letters finish the word: "___ell", the hard outside of an egg?', 2, '"sh" + "ell" makes "shell".', 'Try each sound in front of "ell".'),
    ('30000000-0000-0000-0000-000000000058', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 1, 'Read: "Pam has a pet frog. It likes to hop in the pond." What pet does Pam have?', 2, 'The story says Pam has a pet frog.', 'Look at the first sentence.'),
    ('30000000-0000-0000-0000-000000000059', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 2, 'Read: "Pam has a pet frog. It likes to hop in the pond." Where does the frog like to hop?', 0, 'The story says the frog likes to hop in the pond.', 'Look at the second sentence.'),
    ('30000000-0000-0000-0000-000000000060', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 3, 'Read: "Dad made soup. It was too hot, so we waited." Why did they wait?', 2, 'They waited because the soup was too hot to eat.', 'Find the word "so".'),
    ('30000000-0000-0000-0000-000000000061', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 4, 'Read: "Kim put on her coat and hat. Snow fell all day." What was the weather like?', 2, 'The story says snow fell all day.', 'Why would Kim need a coat and hat?'),
    ('30000000-0000-0000-0000-000000000062', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 5, 'Read: "Max lost his ball. He looked under the bed and found it." Where was the ball?', 0, 'Max looked under the bed and found it there.', 'Where did Max look?'),
    ('30000000-0000-0000-0000-000000000063', 'G1-ENG-COMP-01', 'COMPREHENSION_G1', 6, 'Read: "The bird made a nest. Then it laid three eggs." What did the bird do first?', 2, 'First the bird made a nest, then it laid eggs.', 'The word "then" tells you what came next.'),
    ('30000000-0000-0000-0000-000000000064', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 1, 'Which sentence is written correctly?', 2, 'A sentence starts with a capital letter and ends with an end mark.', 'Check the first letter and the last mark.'),
    ('30000000-0000-0000-0000-000000000065', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 2, 'Which mark goes at the end of a question?', 1, 'A question ends with a question mark: ?', 'Questions ask something.'),
    ('30000000-0000-0000-0000-000000000066', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 3, 'Which mark finishes this sentence: "Where is my hat_"', 0, '"Where is my hat?" asks something, so it needs a question mark.', 'Is this sentence asking something?'),
    ('30000000-0000-0000-0000-000000000067', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 4, 'Which mark shows strong feeling, like "Wow, we won_"', 1, 'An exclamation mark shows excitement or strong feeling.', 'Imagine shouting it happily.'),
    ('30000000-0000-0000-0000-000000000068', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 5, 'Which word should start with a capital letter?', 0, 'Names of people, like Sam, always start with a capital letter.', 'Which word is someone''s name?'),
    ('30000000-0000-0000-0000-000000000069', 'G1-ENG-PUNCT-01', 'PUNCTUATION_G1', 6, 'Which sentence uses a capital and an end mark the right way?', 1, 'The word "I" is always a capital, and the sentence ends with a period.', 'The word I is always big.'),
    ('30000000-0000-0000-0000-000000000070', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 1, 'Which word is an action word (verb)?', 2, '"jump" is something you can do, so it is an action word.', 'Which one can you do?'),
    ('30000000-0000-0000-0000-000000000071', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 2, 'Which word is a naming word (noun)?', 0, '"apple" names a thing, so it is a noun.', 'Which one can you hold or see?'),
    ('30000000-0000-0000-0000-000000000072', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 3, 'In "The cat sleeps," which word is the action word?', 0, '"sleeps" tells what the cat does.', 'What is the cat doing?'),
    ('30000000-0000-0000-0000-000000000073', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 4, 'In "Mom drives the car," which word is a naming word?', 2, '"car" names a thing. ("Mom" is a naming word too!)', 'Look for a person, place, or thing.'),
    ('30000000-0000-0000-0000-000000000074', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 5, 'Which word is an action word?', 0, '"eat" is something you do.', 'Can you do it?'),
    ('30000000-0000-0000-0000-000000000075', 'G1-ENG-NOUNVERB-01', 'NOUNS_VERBS_G1', 6, 'Which group has only naming words?', 1, 'Ball, park, and teacher all name a thing, a place, or a person.', 'Each word must be a person, place, or thing.'),
    ('30000000-0000-0000-0000-000000000076', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 1, 'What is the word for more than one "dog"?', 0, 'Most words just add -s: dog becomes dogs.', 'Add one letter to the end.'),
    ('30000000-0000-0000-0000-000000000077', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 2, 'What is the word for more than one "bus"?', 2, 'Words ending in s add -es: bus becomes buses.', 'Words ending in s, x, sh, or ch add -es.'),
    ('30000000-0000-0000-0000-000000000078', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 3, 'What is the word for more than one "dish"?', 0, 'Words ending in sh add -es: dish becomes dishes.', 'Say "dishs" out loud. It is hard to say!'),
    ('30000000-0000-0000-0000-000000000079', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 4, 'Which word means more than one?', 1, '"hats" ends in -s, so it means more than one hat.', 'Look for the -s at the end.'),
    ('30000000-0000-0000-0000-000000000080', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 5, 'Finish the sentence: "I see two ___."', 2, 'Two means more than one, so we say "two birds".', 'Two is more than one.'),
    ('30000000-0000-0000-0000-000000000081', 'G1-ENG-PLURAL-01', 'PLURALS_G1', 6, 'What is the word for more than one "fox"?', 2, 'Words ending in x add -es: fox becomes foxes.', 'Words ending in x add -es.'),
    ('30000000-0000-0000-0000-000000000082', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 1, 'What is the opposite of "hot"?', 2, 'Hot and cold are opposites.', 'Think of ice.'),
    ('30000000-0000-0000-0000-000000000083', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 2, 'What is the opposite of "up"?', 1, 'Up and down are opposites.', 'Which way does a ball fall?'),
    ('30000000-0000-0000-0000-000000000084', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 3, 'What is the opposite of "happy"?', 2, 'Happy and sad are opposites.', 'How do you feel when you drop your ice cream?'),
    ('30000000-0000-0000-0000-000000000085', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 4, 'What is the opposite of "open"?', 2, 'Open and closed are opposites.', 'Think of a door you shut.'),
    ('30000000-0000-0000-0000-000000000086', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 5, 'What is the opposite of "fast"?', 2, 'Fast and slow are opposites.', 'A snail moves this way.'),
    ('30000000-0000-0000-0000-000000000087', 'G1-ENG-OPPOSITE-01', 'OPPOSITES_G1', 6, 'Which two words are opposites?', 2, 'Day and night are opposites. Big and large mean the same thing.', 'Opposites mean very different things.');
INSERT INTO exercise_choices (exercise_id, choice_index, choice_text) VALUES
    ('30000000-0000-0000-0000-000000000001', 0, '6'), ('30000000-0000-0000-0000-000000000001', 1, '5'), ('30000000-0000-0000-0000-000000000001', 2, '7'),
    ('30000000-0000-0000-0000-000000000002', 0, '14'), ('30000000-0000-0000-0000-000000000002', 1, '16'), ('30000000-0000-0000-0000-000000000002', 2, '13'),
    ('30000000-0000-0000-0000-000000000003', 0, '19'), ('30000000-0000-0000-0000-000000000003', 1, '9'), ('30000000-0000-0000-0000-000000000003', 2, '90'),
